import {shuffleOptions,choiceOptions} from './option-order.mjs?v=1.1.2';
import {createJourney,restoreJourney,mergeMetrics,difficultyFor,makeClient,installationSummary} from './career-core.mjs?v=1.1.2';
import {ShiftSession,portrait,difficultyMarkup,recordsMarkup,rememberReport} from './shift-session.mjs?v=1.1.2';
import { INTRO, FIELDS, SAVE_VERSION, validateField, nearestIds, saoPauloDate, addDays, isCorrectBooking, routePosition } from './core.mjs?v=1.1.2';

const app=document.querySelector('#app');
const modalRoot=document.querySelector('#modal-root');
const SOLO_MODES=['free','lt32-free','activation-free','heist-free','recovery-free'];
const SAVE_KEY='andersons-save-v1', PREFS_KEY='andersons-prefs-v1', STATS_KEY='andersons-stats-v1';
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
function write(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{return false;}}
function remove(key){try{localStorage.removeItem(key);}catch{}}
let prefs={sound:true,difficulty:'normal',reduceMotion:matchMedia('(prefers-reduced-motion: reduce)').matches,...read(PREFS_KEY,{})};
let stats={attempts:0,wins:0,...read(STATS_KEY,{})};
let state=null, view='menu', modal=null, timers=new Set(), mapFrame=0, mapPoints=null, lock=false, toastTimer=0, previousFocus=null, failTimer=0;
let mapLastSave=0,desk=null;
const $=selector=>document.querySelector(selector);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,extra='')=>`<svg class="icon ${extra}" aria-hidden="true"><use href="#i-${name}"/></svg>`;
const delay=(fn,ms)=>{const id=setTimeout(()=>{timers.delete(id);fn();},ms);timers.add(id);return id;};
function clearJobs(){window.speechSynthesis?.cancel();timers.forEach(clearTimeout);timers.clear();cancelAnimationFrame(mapFrame);mapFrame=0;lock=false;}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3000);}
function persist(){if(state&&!state.failed&&!SOLO_MODES.includes(state.installationMode)){if(desk&&desk.context.caseId===state.caseId&&['intro','map','intake','calendar','success'].includes(state.phase)&&!lock)desk.checkpoint(state);write(SAVE_KEY,{...state,version:SAVE_VERSION});}}
function savedGame(){const s=read(SAVE_KEY,null);return s?.version===SAVE_VERSION&&['intro','map','intake','calendar','success','workshop','activation','heist','recovery'].includes(s.phase)&&Array.isArray(s.messages)?s:null;}
const audio={
  ctx:null, interval:null, beat:0,
  init(){if(!prefs.sound)return;try{this.ctx??=new (window.AudioContext||window.webkitAudioContext)();if(this.ctx.state==='suspended')this.ctx.resume().catch(()=>{});}catch{}},
  tone(freq=440,duration=.1,type='sine',volume=.035){if(!prefs.sound||!this.ctx||document.hidden)return;try{const osc=this.ctx.createOscillator(),gain=this.ctx.createGain(),now=this.ctx.currentTime;osc.type=type;osc.frequency.setValueAtTime(freq,now);gain.gain.setValueAtTime(0,now);gain.gain.linearRampToValueAtTime(volume,now+.015);gain.gain.exponentialRampToValueAtTime(.0001,now+duration);osc.connect(gain);gain.connect(this.ctx.destination);osc.start(now);osc.stop(now+duration+.03);}catch{}},
  effect(kind){this.init();if(kind==='fail'){this.tone(155,.5,'sawtooth',.03);setTimeout(()=>this.tone(110,.6,'triangle',.05),130);}else if(kind==='success'){[392,494,587,784].forEach((n,i)=>setTimeout(()=>this.tone(n,.35,'triangle',.04),i*95));}else if(kind==='copy')this.tone(880,.08,'sine',.025);else this.tone(kind==='message'?720:480,.08,'sine',.025);},
  start(){this.init();if(this.interval)return;const notes=[110,0,164.81,0,130.81,0,146.83,164.81];this.interval=setInterval(()=>{if(view==='game'&&!['workshop','activation','heist','recovery'].includes(state?.phase)&&!modal&&!state?.failed&&prefs.sound){const n=notes[this.beat++%notes.length];if(n)this.tone(n,.32,'sine',.015);}},420);}
};
function controls(menu=false){return `<div class="${menu?'menu-controls':'topbar-right'}">${!menu?'<span class="live-status"><i class="dot"></i> EXPEDIENTE EM ANDAMENTO</span>':''}<button class="icon-button" data-action="sound" aria-label="${prefs.sound?'Desativar':'Ativar'} som" title="${prefs.sound?'Desativar':'Ativar'} som">${icon(prefs.sound?'volume':'muted')}</button><button class="icon-button" data-action="help" aria-label="Como jogar" title="Como jogar">${icon('help')}</button>${!menu?`<button class="icon-button" data-action="menu-dialog" aria-label="Menu do jogo" title="Menu">${icon('menu')}</button>`:''}</div>`;}
function renderMenu(){
 const saved=savedGame();
 return `<main class="menu-page"><header class="menu-top"><div class="micro-brand"><span class="brand-mark">A</span> ANDERSONS CORP.</div><div class="kicker"><i class="dot"></i> RECURSOS HUMANOS EM ALERTA</div>${controls(true)}</header><section class="menu-hero"><div class="menu-content"><span class="edition"><i class="dot"></i> CINCO ATOS · INSTALANDO E ROUBANDO</span><img class="title-logo" src="./assets/logo.png" alt="OS ANDERSONS — INSTALANDO E ROUBANDO" width="1760" height="880"><h1 class="menu-title"><small>OS</small>ANDERSONS<span>INSTALANDO E ROUBANDO</span></h1><p class="menu-copy">Você é Anderson. O cliente também.<br><strong>Seu maior desafio? Continuar empregado.</strong></p>${difficultyMarkup(prefs.difficulty)}<div class="button-row"><button class="btn btn-primary start-button" data-action="new-game">Começar expediente ${icon('arrow')}</button></div><button class="btn btn-secondary free-workshop-button" data-action="lt32-solo">${icon('car')} Jogar só a instalação 2D ${icon('arrow')}</button><button class="activation-solo-link" data-action="activation-solo">Jogar só a ativação · Ato 3 →</button><button class="activation-solo-link heist-solo-link" data-action="heist-solo">Jogar O grande roubo · Ato 4 →</button><button class="activation-solo-link recovery-solo-link" data-action="recovery-solo">Jogar Atuação anti furto · Ato 5 →</button><button class="practice-link" data-action="free-workshop">Praticar na oficina 3D · LCV5 ↗</button><button class="release-credits-link" data-action="credits">CRÉDITOS · VERSÃO 1.1</button><button class="records-link" data-action="records">★ Mural de conquistas e avaliações</button>${saved&&(!saved.completed||saved.phase==='success'||saved.phase==='activation'&&saved.activationCompleted||saved.phase==='heist'&&saved.heistCompleted)?`<button class="continue-button" data-action="continue">${icon('play')} ${saved.phase==='success'?'Continuar para a instalação':saved.phase==='workshop'&&saved.workshopCompleted?'Continuar para a ativação':saved.phase==='activation'&&saved.activationCompleted?'Continuar para O grande roubo':saved.phase==='heist'&&saved.heistCompleted?'Continuar para Atuação anti furto':'Continuar de onde parei'}</button>`:''}${saved?.recoveryCompleted?`<section class="campaign-finished"><strong>✓ Expediente concluído.</strong><p>Você sobreviveu aos cinco atos. A Cat está orgulhosa. Disfarçadamente.</p><button data-action="continue">Rever o encerramento →</button></section>`:''}<div class="menu-hint"><span>${icon('chat')} Escolhas perigosas</span><span>${icon('pin')} Técnicos em movimento</span></div>${stats.wins?`<p class="menu-toast">${icon('check')} Ato 1 concluído ${stats.wins} ${stats.wins===1?'vez':'vezes'}. A Cat está de olho.</p>`:''}</div><div class="hero-art" aria-label="Cat, a chefe do setor"><div class="hero-halo"></div><div class="cat-dossier"><div class="dossier-clip"></div><div class="dossier-meta"><span>ANDERSONS CORP.</span><span>ID: CAT-001</span></div><img class="cat-hero" src="./assets/cat.jpeg" alt="Cat, a mascote e chefe do setor: felina loira de olhos claros" width="2048" height="1143"><div class="dossier-info"><div><h2>CAT</h2><p>CHEFE DO SETOR · SUA ÚLTIMA CHANCE</p></div><div class="id-barcode" aria-hidden="true"></div></div></div><div class="cat-quote">“EU ESTOU OBSERVANDO.”</div><div class="sticker"><small>POLÍTICA DA EMPRESA</small>TOLERÂNCIA A ERROS:<br>ZERO.</div></div></section><footer class="menu-bottom"><div class="act-preview"><span class="act-number">01–05</span><div><strong>AGENDAR · INSTALAR · ATIVAR · ROUBAR · RECUPERAR</strong><p>O desafio final: recuperar o Ford Ka com a Rô.</p></div></div><div class="mono">CAMPANHA INDIVIDUAL<br>PC + CELULAR · V1.1.2</div></footer></main>`;
}
const PHASES=['Atendimento','Técnico','Cadastro','Agenda'];
function stage(){return {intro:0,map:1,intake:2,calendar:3,success:4}[state.phase]??0;}
function chrome(content){const s=stage();return `<div class="game-shell"><header class="topbar"><div class="micro-brand"><span class="brand-mark">A</span> OS ANDERSONS</div>${controls()}</header><main class="game-main"><div class="chapter-strip"><div class="chapter-label"><span class="number">01</span><div><h1>AGENDAMENTO</h1><p>Andersons Corp. / Seu primeiro expediente</p></div></div><nav class="progress-track" aria-label="Progresso do ato">${PHASES.map((name,i)=>`<span class="progress-step ${i===s?'active':i<s?'done':''}" ${i===s?'aria-current="step"':''}><span class="step-dot">${i<s?icon('check'):i+1}</span>${name}</span>`).join('')}</nav></div>${desk?.markup(state.phase)||''}${content}<footer class="game-footnote"><span>${icon('lock')} Seu progresso é salvo neste navegador.</span><span>CAT NÃO ACEITA DESCULPAS.</span></footer></main></div>`;}
function heading(label,title,description,tag=''){return `<div class="scene-heading"><div><div class="eyebrow">${label}</div><h2 tabindex="-1" id="scene-title">${title}</h2>${description?`<p>${description}</p>`:''}</div>${tag?`<span class="scene-tag">${tag}</span>`:''}</div>`;}
function catAdvice(text){return `<div class="cat-advice">${portrait('cat',state?.phase==='success'?'happy':desk?.mood||'calm','cat-avatar')}<div><small>CAT · CHEFE DO SETOR</small><p>${text}</p></div></div>`;}
function message(message){if(message.voice&&!state.voicesOpened?.[message.copyKey])return `<div class="bubble"><span class="bubble-name">Anderson · Cliente</span><button class="voice-message" data-action="open-voice" data-key="${message.copyKey}"><span class="voice-wave">▶ ▂▅▃▆▂▇▃▅▂</span><br>Mensagem de voz · 00:08<br><small>Toque para ouvir e ler a transcrição</small></button></div>`;return `<div class="bubble ${message.sender==='player'?'out':''}">${message.sender==='client'?'<span class="bubble-name">Anderson · Cliente</span>':''}<div>${esc(message.text)}</div><span class="bubble-time">09:${String(message.time??0).padStart(2,'0')}${message.sender==='player'?icon('check'):''}</span>${message.copyKey?`<button class="copy-response" data-action="copy" data-key="${message.copyKey}">${icon('copy')} ${state.clipboard?.key===message.copyKey?'Resposta copiada':'Copiar resposta'}</button>`:''}</div>`;}
function chatWindow(messages,typing=false,{intake=false}={}){return `<section class="chat-window" aria-label="WhatsApp corporativo"><div class="window-cap"><span>${icon('chat')} WHATSAPP CORPORATIVO</span><div class="window-lights" aria-hidden="true"><i></i><i></i><i></i></div></div><div class="chat-header"><div class="avatar">A</div><div class="chat-person"><strong>Anderson · Cliente</strong><small>${typing?'digitando…':'online'}</small></div>${icon('lock')}</div><div class="chat-messages" role="log" aria-label="Conversa com o cliente" aria-live="polite"><span class="chat-date">HOJE</span><p class="chat-security">${icon('lock')} Ambiente fictício · Atendimento corporativo</p>${messages.map(message).join('')}${typing?'<div class="bubble typing-bubble" role="status" aria-label="Cliente digitando"><i></i><i></i><i></i></div>':''}</div><div class="chat-input"><div class="input-placeholder">${intake?'Selecione uma pergunta para o cliente':'Escolha uma resposta no painel de atendimento'}</div>${icon('arrow')}</div></section>`;}
function decisionBrief(question){return `<div class="decision-brief" role="note" aria-label="Orientação deste atendimento"><small>ORIENTAÇÃO DO SETOR</small><p>${esc(question.brief)}</p></div>`;}
function choices(options,action,decision){return `<div class="choices">${choiceOptions(options,state.caseId,decision).map(({text,index},position)=>`<button class="choice" data-action="${action}" data-index="${index}" data-position="${position}" style="animation-delay:${position*35}ms"><span class="choice-number">${position+1}</span><span class="choice-text">${esc(text)}</span></button>`).join('')}</div>`;}
function introView(){
 const step=state.introStep;
 const typing=!!state.awaiting;
 const ready=!typing&&state.introReady;
 return chrome(`${heading('ETAPA 01 / ATENDIMENTO','Uma nova mensagem. Um novo Anderson.','Atenda o cliente. Pense bem antes de responder.','<i class="dot"></i> CANAL CORPORATIVO')}<div class="scene-grid">${chatWindow(state.messages,typing)}<section aria-label="Respostas de atendimento">${catAdvice(step===0?'O QUE VOCÊ IRÁ FAZER?':'EXPLIQUE DIREITO, ANDERSON!')}<div class="decision-heading"><strong>${step===0?'Como você vai responder?':'Como funciona o rastreador?'}</strong><span>${Math.min(step+1,2)} / 2</span></div>${ready?decisionBrief(INTRO[step])+choices(INTRO[step].options,'intro-choice','intro:'+step):`<div class="waiting-panel">${icon('chat')}<span>${state.awaiting==='date'?'O cliente está pensando no agendamento…':'O cliente está digitando…'}</span><small>Prepare o seu melhor atendimento.</small></div>`}<p class="decision-note">${icon('bolt')} Uma resposta errada pode custar seu emprego.<span class="keyboard-hint">Teclas <kbd class="keyboard-key">1–5</kbd></span></p></section></div>`);
}
