 [[80,80],[440,80],[440,350],[80,350]],
 [[260,80],[800,80],[800,210],[260,210]],
 [[620,80],[920,80],[920,490],[620,490]],
 [[80,210],[620,210],[620,490],[80,490]],
 [[260,350],[800,350],[800,490],[260,490]],
 [[440,80],[920,80],[920,350],[440,350]]
