const CLIENT_ROUTE=[[440,80],[800,80],[800,490],[260,490],[260,210],[440,210]];
function cityMap(){return `<svg class="city-map" viewBox="0 0 1000 570" preserveAspectRatio="none" aria-hidden="true"><defs><pattern id="map-grain" width="14" height="14" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r=".7" fill="#aac3b8" opacity=".09"/></pattern></defs><rect width="1000" height="570" fill="#1b3036"/><path d="M0 33Q180 110 320 42T600 25T1000 17L1000 0H0Z" fill="#25454a"/><g fill="#223d40" stroke="#2e4a4b" stroke-width="2"><rect x="108" y="107" width="124" height="76" rx="9"/><rect x="288" y="107" width="124" height="76" rx="9"/><rect x="468" y="107" width="124" height="76" rx="9"/><rect x="648" y="107" width="124" height="76" rx="9"/><rect x="828" y="107" width="64" height="76" rx="9"/><rect x="108" y="237" width="124" height="86" rx="9"/><rect x="288" y="237" width="124" height="86" rx="9"/><rect x="468" y="237" width="124" height="86" rx="9"/><rect x="648" y="237" width="124" height="86" rx="9"/><rect x="828" y="237" width="64" height="86" rx="9"/><rect x="108" y="377" width="124" height="86" rx="9"/><rect x="288" y="377" width="124" height="86" rx="9"/><rect x="468" y="377" width="124" height="86" rx="9"/><rect x="648" y="377" width="124" height="86" rx="9"/><rect x="828" y="377" width="64" height="86" rx="9"/></g><g stroke="#344a50" stroke-width="24" fill="none"><path d="M0 80H1000M0 210H1000M0 350H1000M0 490H1000M80 0V570M260 0V570M440 0V570M620 0V570M800 0V570M920 0V570"/></g><g stroke="#60756f" stroke-width="1.5" stroke-dasharray="7 9" fill="none" opacity=".6"><path d="M0 80H1000M0 210H1000M0 350H1000M0 490H1000M80 0V570M260 0V570M440 0V570M620 0V570M800 0V570M920 0V570"/></g><rect x="293" y="241" width="114" height="77" rx="8" fill="#2b4a3b"/><g fill="#4c6951"><circle cx="312" cy="257" r="8"/><circle cx="389" cy="301" r="9"/><circle cx="315" cy="301" r="6"/><circle cx="386" cy="258" r="7"/></g><g font-family="system-ui,sans-serif" fill="#98b5a6" font-size="10" text-anchor="middle" letter-spacing="1.5"><text x="350" y="282">PRAÇA</text><text x="530" y="151">CENTRO</text><text x="710" y="286">MERCADO</text><text x="170" y="425">OFICINA</text><text x="530" y="425">ESTAÇÃO</text></g><rect x="130" y="385" width="79" height="15" rx="3" fill="#9b8a57" opacity=".6"/><path d="M655 402h110v41H655Z" fill="#2d4546"/><g fill="#52645d" opacity=".5"><rect x="121" y="124" width="25" height="39" rx="2"/><rect x="154" y="124" width="56" height="15" rx="2"/><rect x="154" y="146" width="56" height="17" rx="2"/><rect x="304" y="120" width="90" height="14" rx="2"/><rect x="304" y="145" width="37" height="24" rx="2"/><rect x="349" y="145" width="45" height="24" rx="2"/><rect x="669" y="124" width="80" height="41" rx="3"/><rect x="305" y="398" width="42" height="46" rx="3"/><rect x="355" y="398" width="40" height="46" rx="3"/></g><g fill="#c5d3c8" font-family="monospace" font-size="9" letter-spacing="2" opacity=".5"><text x="45" y="38">N ↑</text><text x="855" y="546">CENTRO / BR</text></g><rect width="1000" height="570" fill="url(#map-grain)"/></svg>`;}
function mapView(){return chrome(`${heading('ETAPA 02 / DESPACHO','Quem está mais perto?','O cliente quer uma data. Primeiro, encontre o técnico mais próximo.','<i class="dot"></i> LOCALIZAÇÃO AO VIVO')}<div class="map-layout"><section class="map-card" aria-label="Mapa com o cliente e seis técnicos"><div class="map-bar"><span>${icon('pin')} CENTRAL DE DESPACHO</span><span class="mono">${prefs.reduceMotion?'MOVIMENTO REDUZIDO':'POSIÇÕES EM MOVIMENTO'}</span></div><div class="map-world">${cityMap()}<div class="map-marker client" id="client-marker" data-label="CLIENTE" role="img" aria-label="Localização do cliente">${icon('pin')}</div>${Array.from({length:6},(_,i)=>`<button class="map-marker ${state.tech===i+1?'chosen':''}" id="tech-${i+1}" data-action="select-tech" data-id="${i+1}" data-label="ANDERSON ${String(i+1).padStart(2,'0')}" aria-label="Escolher técnico Anderson ${String(i+1).padStart(2,'0')}" ${state.tech?'disabled':''}>${icon('car')}</button>`).join('')}</div><div class="map-legend"><span><i class="legend-circle"></i> CLIENTE</span><span><i class="legend-square"></i> TÉCNICO DISPONÍVEL</span><span class="muted">DISTÂNCIA EM LINHA RETA</span></div></section><aside class="dispatch-side">${catAdvice('O MAIS PERTO. NÃO O MAIS SIMPÁTICO.')}<div class="brief-card"><div class="eyebrow">SOLICITAÇÃO #001</div><h3>“Quando tem data?”</h3><p>Os seis técnicos estão na rua. Observe o mapa e toque no que estiver mais perto do cliente.</p><div class="divider"></div><div class="brief-stat"><span>Técnicos disponíveis</span><strong>06</strong></div><div class="brief-stat"><span>Cliente aguardando</span><strong>Anderson</strong></div></div><p class="dispatch-tip">A escolha considera as posições no instante do clique.<br><br>Não precisa ter pressa. Precisa acertar.</p>${state.tech?`<div class="dispatch-ok"><p>${icon('check')} Anderson ${String(state.tech).padStart(2,'0')} designado. Boa escolha!</p><button class="btn btn-primary btn-small" data-action="begin-intake">Abrir cadastro ${icon('arrow')}</button></div>`:''}</aside></div>`);}
function computeMap(){const t=(state.mapElapsed??0)*difficultyFor(state.journey?.difficulty).mapSpeed,seed=state.mapSeed??0;return {client:routePosition(CLIENT_ROUTE,190+seed*.7+t*21),techs:ROUTES.map((route,i)=>({id:i+1,...routePosition(route,seed*(i+1)*.47+150*i+t*(17+i*2))}))};}
function startMap(){let last=performance.now();mapLastSave=last;function tick(now){if(view!=='game'||state.phase!=='map')return;const dt=Math.min((now-last)/1000,.06);last=now;if(!modal&&!state.tech&&!prefs.reduceMotion&&!document.hidden)state.mapElapsed+=dt;mapPoints=computeMap();const set=(el,p)=>{if(!el)return;el.style.left=`${p.x/10}%`;el.style.top=`${p.y/570*100}%`;el.dataset.edge=p.x<120?'left':p.x>880?'right':'';};set($('#client-marker'),mapPoints.client);mapPoints.techs.forEach(p=>set($(`#tech-${p.id}`),p));if(now-mapLastSave>3000){persist();mapLastSave=now;}mapFrame=requestAnimationFrame(tick);}tick(last);}
function tabBar(){return `<div class="desk-tabs" role="tablist" aria-label="Sistema de cadastro"><button class="desk-tab ${state.tab==='form'?'active':''}" role="tab" aria-selected="${state.tab==='form'}" aria-controls="intake-panel" data-action="tab-form">${icon('paste')} Ficha de agendamento <span class="tab-badge">${state.intakeIndex}/3</span></button><button class="desk-tab ${state.tab==='chat'?'active':''}" role="tab" aria-selected="${state.tab==='chat'}" aria-controls="intake-panel" data-action="tab-chat">${icon('chat')} WhatsApp ${state.asked[FIELDS[state.intakeIndex]?.key]&&!state.form[FIELDS[state.intakeIndex]?.key]?'<span class="dot"></span>':''}</button></div>`;}
function intakeForm(){const index=state.intakeIndex,field=FIELDS[index];return `<div class="intake-grid"><section class="form-card"><header class="form-card-header"><div><h3>Ficha de agendamento</h3><p>ATENDIMENTO #001 · TÉCNICO ANDERSON ${String(state.tech).padStart(2,'0')}</p></div>${icon('paste')}</header><div class="form-body">${FIELDS.map((f,i)=>`<div class="field-row ${i<index?'complete':i>index?'future':''}"><label class="field-label" for="field-${f.key}"><span>${i+1}. ${f.label}</span>${i<index?icon('check'):`<span class="field-step">${i===index?'PREENCHA AGORA':'EM SEGUIDA'}</span>`}</label><div class="field-input-row"><input id="field-${f.key}" class="text-input" data-field="${f.key}" value="${esc(state.form[f.key])}" placeholder="${i===index?'Cole a resposta do cliente':'Aguardando etapa anterior'}" autocomplete="off" ${i!==index?'disabled':''}>${i===index?`<button class="btn btn-secondary btn-small" data-action="paste" aria-label="Colar resposta no campo ${f.label}">${icon('paste')} Colar</button>`:''}</div>${i===index?`<p class="field-note">${state.asked[f.key]?'Copie a mensagem do cliente no WhatsApp e cole neste campo.':'Abra o WhatsApp e faça a pergunta correta ao cliente.'}</p>`:''}</div>`).join('')}<div class="form-error" id="form-error" role="alert"></div></div><footer class="form-actions"><button class="btn btn-secondary" data-action="tab-chat">${icon('chat')} ${state.asked[field.key]?'Ver resposta':'Perguntar ao cliente'}</button><button class="btn btn-primary" data-action="save-field">${index===2?'Conferir agenda':'Salvar e continuar'} ${icon('arrow')}</button></footer></section><aside>${catAdvice('PERGUNTE. COPIE. COLE. SEM INVENTAR.')}<div class="brief-card"><div class="eyebrow">O SISTEMA ESTÁ PEDINDO</div><h3>${esc(field.request)}</h3><ol class="instruction-list"><li class="${!state.asked[field.key]?'current':''}"><span>1</span><div><strong>Pergunte</strong>Escolha a pergunta certa no WhatsApp.</div></li><li class="${state.asked[field.key]&&state.clipboard?.key!==field.key?'current':''}"><span>2</span><div><strong>Copie</strong>Use “Copiar resposta” na mensagem recebida.</div></li><li class="${state.clipboard?.key===field.key?'current':''}"><span>3</span><div><strong>Cole e salve</strong>Traga a resposta para esta ficha.</div></li></ol></div></aside></div>`;}
function intakeChat(){const field=FIELDS[state.intakeIndex],answered=state.asked[field.key],typing=!!state.awaiting;return `<div class="intake-chat-grid">${chatWindow(state.intakeMessages,typing,{intake:true})}<section>${catAdvice('FAÇA A PERGUNTA CERTA, ANDERSON.')}<div class="request-strip"><small>INFORMAÇÃO SOLICITADA PELO SISTEMA</small><p>${esc(field.request)}</p></div>${answered?`<div class="received-answer">${icon('check')}<h3>O cliente respondeu.</h3><p>Copie a resposta na mensagem recebida.<br>Depois, abra a ficha e cole no campo solicitado.</p><button class="btn btn-primary" data-action="tab-form">Ir para a ficha ${icon('arrow')}</button></div>`:typing?`<div class="waiting-panel">${icon('chat')}<span>O cliente está digitando…</span><small>Aguarde a resposta para preencher a ficha.</small></div>`:`<div class="decision-heading"><strong>O que você vai perguntar?</strong><span>${state.intakeIndex+1} / 3</span></div>${decisionBrief(field)}${choices(field.options,'intake-choice','intake:'+field.key)}`}<p class="decision-note">${icon('bolt')} A Cat está acompanhando esta conversa.</p></section></div>`;}
function intakeView(){return chrome(`${heading('ETAPA 03 / CADASTRO','Agora, preencha a ficha.','Converse com o cliente e traga as respostas para o sistema.','FICHA #001')}${tabBar()}<div id="intake-panel" role="tabpanel">${state.tab==='form'?intakeForm():intakeChat()}</div>`);}
function formatDate(iso,options={day:'2-digit',month:'long'}){return new Intl.DateTimeFormat('pt-BR',{...options,timeZone:'UTC'}).format(new Date(iso+'T12:00:00Z'));}
function calendarView(){return chrome(`${heading('ETAPA 04 / CONFIRMAÇÃO','Feche esse agendamento.','O cliente já informou quando pode. Confirme a data e o horário.','ÚLTIMA ETAPA')}<div class="calendar-layout"><section class="calendar-card"><p class="section-label"><span class="tiny-number">1</span> Escolha a data</p><div class="date-grid" role="group" aria-label="Datas disponíveis">${shuffleOptions([0,1,2],state.caseId,'calendar.days').map((offset)=>{const iso=addDays(state.baseDate,offset);return `<button class="date-option ${state.calendarDay===iso?'selected':''}" data-action="date" data-date="${iso}" aria-pressed="${state.calendarDay===iso}"><small>${['Hoje','Amanhã','Depois de amanhã'][offset]}</small><strong>${iso.slice(-2)}</strong><span>${formatDate(iso,{month:'short',weekday:'short'})}</span></button>`;}).join('')}</div><p class="section-label"><span class="tiny-number">2</span> Escolha o horário</p><div class="time-grid" role="group" aria-label="Horários disponíveis">${shuffleOptions(['09:00','10:00','12:00','14:00','16:00'],state.caseId,'calendar.times').map(time=>`<button class="time-option ${state.calendarTime===time?'selected':''}" data-action="time" data-time="${time}" aria-pressed="${state.calendarTime===time}">${time}</button>`).join('')}</div><div class="calendar-bottom"><div class="calendar-selection">${state.calendarDay&&state.calendarTime?`Agendamento selecionado<strong>${formatDate(state.calendarDay)} · ${state.calendarTime}</strong>`:'Selecione uma data e um horário.'}</div><button class="btn btn-primary" data-action="confirm-booking" ${!state.calendarDay||!state.calendarTime?'disabled':''}>Confirmar agendamento ${icon('check')}</button></div></section><aside>${catAdvice('LEIA O QUE O CLIENTE PEDIU.')}<div class="customer-note"><small>RECADO DO CLIENTE</small><blockquote>“${esc(answerFor(2))}”</blockquote><p>Anderson · WhatsApp corporativo</p></div><div class="booking-summary"><div><span>Cliente</span><strong>${esc(state.form.name)}</strong></div><div><span>Veículo</span><strong>${esc(state.form.vehicle)}</strong></div><div><span>Técnico</span><strong>Anderson ${String(state.tech).padStart(2,'0')}</strong></div><div><span>Data do atendimento</span><strong>${formatDate(state.baseDate)}</strong></div></div></aside></div>`);}
function successView(){return chrome(`<section class="ending"><div class="success-badge">${icon('check')}</div><div class="eyebrow">FIM DO ATO 1 · AGENDAMENTO</div><h2>ATENDIMENTO REALIZADO<br>COM SUCESSO!</h2><p class="level-up">VOCÊ PASSOU DE NÍVEL!</p><div class="receipt"><div class="receipt-header"><strong>AGENDAMENTO #001</strong><span>ANDERSONS CORP.</span></div><div class="receipt-row"><span>Cliente</span><strong>${esc(state.form.name)}</strong></div><div class="receipt-row"><span>Veículo</span><strong>${esc(state.form.vehicle)}</strong></div><div class="receipt-row"><span>Técnico</span><strong>Anderson ${String(state.tech).padStart(2,'0')}</strong></div><div class="receipt-row"><span>Data e horário</span><strong>${formatDate(addDays(state.baseDate,state.customer?.dayOffset||1))} · ${state.customer?.time||'12:00'}</strong></div><div class="receipt-stamp">VOCÊ CONTINUA EMPREGADO</div></div>${catAdvice('NÃO FEZ MAIS QUE A OBRIGAÇÃO. MAS PARABÉNS.')}<div class="button-row"><button class="btn btn-primary" data-action="next-act">Continuar para a instalação ${icon('arrow')}</button><button class="btn btn-secondary" data-action="return-menu">Tela inicial</button></div><p class="end-note">PRÓXIMO ATO · INSTALAÇÃO 2D / LT-32 PRO</p></section>`);}

function workshopView(){
 const recovery=state.phase==='recovery',heist=state.phase==='heist',activation=state.phase==='activation',practice=!recovery&&!heist&&!activation&&state.installationMode==='free',mode=recovery||heist||activation?(SOLO_MODES.includes(state.installationMode)?'solo':'campaign'):practice?'free':state.installationMode==='lt32-free'?'solo':'campaign';
 const source=recovery?'recovery.html':heist?'heist.html':activation?'activation.html':practice?'workshop.html':'lt32.html';
 return `<main class="workshop-page"><iframe id="workshop-frame" src="./${source}?mode=${mode}&v=1.1.2" title="${recovery?'Ato 5 · Atuação anti furto — OS ANDERSONS':heist?'Ato 4 · O grande roubo — OS ANDERSONS':activation?'Ato 3 · Ativação — OS ANDERSONS':practice?'Prática 3D LCV5':'Instalação 2D LT-32 PRO — OS ANDERSONS'}" allow="fullscreen; clipboard-write" allowfullscreen></iframe></main>`;
}
function sendWorkshopContext(){
 const frame=$('#workshop-frame');if(!frame||!state)return;
 const payload={caseId:state.caseId,mode:state.installationMode,client:state.form?.name||'Anderson',vehicle:state.form?.vehicle||'Veículo de treinamento',installationLocation:state.installationLocation||'rear-side',installation:state.journey?.installation||null,journey:state.journey,difficulty:state.journey?.difficulty||prefs.difficulty,tech:state.tech,prefs};
 if(state.installationMode==='campaign'&&state.baseDate)payload.appointment=formatDate(addDays(state.baseDate,state.customer?.dayOffset||1))+' · '+(state.customer?.time||'12:00');
 frame.contentWindow.postMessage({type:'andersons-context',payload},location.origin);
}
function beginWorkshop(mode){
 clearJobs();closeModal();
 if(mode==='free')state={version:SAVE_VERSION,phase:'workshop',installationMode:'free',caseId:'free',messages:[],form:{name:'Anderson · Oficina livre',vehicle:'Veículo de treinamento'}};
 else if(mode==='lt32-free')state={version:SAVE_VERSION,phase:'workshop',installationMode:'lt32-free',caseId:'lt32-solo-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6),messages:[],form:{name:'Anderson · Instalação livre',vehicle:'Veículo de treinamento'}};
 else{if(!state)return;state.phase='workshop';state.installationMode='campaign';state.completed=false;state.caseId??='anderson-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7);}
 view='game';ensureJourney();persist();audio.start();render();window.scrollTo(0,0);
}
function beginActivation(mode){
 clearJobs();closeModal();
 if(mode==='activation-free')state={version:SAVE_VERSION,phase:'activation',installationMode:'activation-free',caseId:'activation-solo-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7),messages:[],form:{name:'Anderson da Silva Anderson',vehicle:'Ford Ka'},installationLocation:'rear-side',workshopCompleted:true};
 else{if(!state||!state.workshopCompleted||state.installationMode==='free')return;state.phase='activation';state.completed=false;}
 view='game';ensureJourney();persist();audio.start();render();window.scrollTo(0,0);
}
function beginHeist(mode){
 clearJobs();closeModal();
 if(mode==='heist-free')state={version:SAVE_VERSION,phase:'heist',installationMode:'heist-free',caseId:'heist-solo-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7),messages:[],form:{name:'Anderson da Silva Anderson',vehicle:'Ford Ka'},workshopCompleted:true,activationCompleted:true};
 else{if(!state||!state.activationCompleted||state.installationMode==='free')return;state.phase='heist';state.completed=false;}
 view='game';ensureJourney();persist();audio.start();render();window.scrollTo(0,0);
}
function beginRecovery(mode){
 clearJobs();closeModal();
 if(mode==='recovery-free')state={version:SAVE_VERSION,phase:'recovery',installationMode:'recovery-free',caseId:'recovery-solo-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7),messages:[],form:{name:'Anderson da Silva Anderson',vehicle:'Ford Ka'},workshopCompleted:true,activationCompleted:true,heistCompleted:true};
 else{if(!state||!state.heistCompleted||state.failed||state.installationMode==='free')return;state.phase='recovery';state.completed=false;}
 view='game';ensureJourney();persist();audio.start();render();window.scrollTo(0,0);
}
window.addEventListener('message',event=>{
 const frame=$('#workshop-frame');if(!frame||event.source!==frame.contentWindow||event.origin!==location.origin)return;
 const recovery=state.phase==='recovery',heist=state.phase==='heist',activation=state.phase==='activation',expected=recovery?'andersons-recovery':heist?'andersons-heist':activation?'andersons-activation':'andersons-workshop';if(event.data?.type!==expected)return;
 const {event:action,payload}=event.data;
 if(action==='ready')sendWorkshopContext();
 else if(action==='metrics'){const act=recovery?5:heist?4:activation?3:2;if(payload?.act===act){state.journey=mergeMetrics(state.journey,act,payload.metrics);if(!state.failed)persist();}}
 else if(action==='retry'&&difficultyFor(state.journey?.difficulty).checkpoints&&(state.failed||state.pendingRetry)){state.failed=false;state.pendingRetry=false;persist();}
 else if(action==='installation'&&!recovery&&!heist&&!activation){state.journey.installation=installationSummary(payload);state.installationLocation=state.journey.installation.location;persist();}
 else if(action==='sound')toggleSound();
 else if(action==='menu')returnMenu();
 else if(action==='new-case')newGame();
 else if(action==='replay'&&recovery&&state.recoveryCompleted&&!state.failed)beginRecovery('recovery-free');
 else if(action==='recovery'&&heist&&state.heistCompleted&&!state.failed)beginRecovery();
 else if(action==='heist'&&activation&&state.activationCompleted)beginHeist();
 else if(action==='activate'&&!recovery&&!heist&&!activation&&state.workshopCompleted){if(['rear-side','rear-trim'].includes(payload?.installationLocation))state.installationLocation=payload.installationLocation;beginActivation();}
 else if(action==='failed'&&state.installationMode!=='free'){state.failed=true;if(!SOLO_MODES.includes(state.installationMode)){if(difficultyFor(state.journey?.difficulty).checkpoints){state.pendingRetry=true;write(SAVE_KEY,{...state,failed:false,version:SAVE_VERSION});}else remove(SAVE_KEY);}}
 else if(['progress','complete'].includes(action)&&!state.failed){
  if(recovery){if(['alert','contact','classify','lecture','tracking','briefing','countdown','chase','stopping','finish'].includes(payload?.phase))state.recoveryStage=payload.phase;if(action==='complete'&&payload?.phase==='finish'){state.recoveryCompleted=true;state.completed=true;state.journey=mergeMetrics(state.journey,5,{...state.journey.acts[5],completed:true});if(!SOLO_MODES.includes(state.installationMode))rememberReport(state.journey);audio.effect('success');}}
  else if(heist){if(['intro','foot','interior','wiring','starting','drive','finish'].includes(payload?.phase))state.heistStage=payload.phase;if(action==='complete'&&payload?.phase==='finish'){state.journey=mergeMetrics(state.journey,4,{...state.journey.acts[4],completed:true});state.heistCompleted=true;state.completed=true;audio.effect('success');}}
  else if(activation){if(['imei','maze','platform','location','handoff','credentials','finish'].includes(payload?.phase))state.activationStage=payload.phase;if(action==='complete'&&payload?.phase==='finish'){state.journey=mergeMetrics(state.journey,3,{...state.journey.acts[3],completed:true});state.activationCompleted=true;state.completed=true;audio.effect('success');}}
  else{if(['arrival','config','workshop','free','monitor','finish','location','wiring','hiding','closing'].includes(payload?.phase))state.workshopStage=payload.phase;if(['rear-side','rear-trim'].includes(payload?.installationLocation))state.installationLocation=payload.installationLocation;if(action==='complete'&&payload?.phase==='finish'){state.journey=mergeMetrics(state.journey,2,{...state.journey.acts[2],completed:true});state.workshopCompleted=true;audio.effect('success');}}
  persist();
 }
});
function render({focus=false}={}){cancelAnimationFrame(mapFrame);document.body.classList.toggle('reduce-motion',prefs.reduceMotion);app.innerHTML=view==='menu'?renderMenu():({intro:introView,map:mapView,intake:intakeView,calendar:calendarView,success:successView,workshop:workshopView,activation:workshopView,heist:workshopView,recovery:workshopView}[state.phase]());document.title=view==='menu'?'OS ANDERSONS — Instalando e Roubando':`${state.phase==='recovery'?'Ato 5 · Atuação anti furto':state.phase==='heist'?'Ato 4 · O grande roubo':state.phase==='activation'?'Ato 3 · Ativação':state.phase==='workshop'?'Ato 2 · '+(state.installationMode==='free'?'Prática 3D':'Instalação LT-32 PRO'):'Ato 1 · '+(state.phase==='success'?'Concluído':PHASES[Math.min(stage(),3)])} | OS ANDERSONS`;document.querySelectorAll('.chat-messages').forEach(el=>el.scrollTop=el.scrollHeight);if(view==='game'&&state.phase==='map')startMap();if(view==='game'&&['workshop','activation','heist','recovery'].includes(state.phase))$('#workshop-frame')?.addEventListener('load',sendWorkshopContext);if(focus&&!modal)$('#scene-title')?.focus({preventScroll:true});}
function showModal(html,kind='generic'){if(!modal)previousFocus=document.activeElement;modal={kind};modalRoot.innerHTML=`<div class="modal-backdrop"><section class="modal ${kind==='prompt'||kind==='failure'?'cat-modal':''} ${kind==='failure'?'failure-modal':kind==='credits'?'credits-modal':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title">${html}</section></div>`;app.inert=true;document.body.style.overflow='hidden';requestAnimationFrame(()=>modalRoot.querySelector('button,input')?.focus());}
function closeModal(){modal=null;modalRoot.innerHTML='';app.inert=false;document.body.style.overflow='';if(previousFocus?.isConnected)previousFocus.focus({preventScroll:true});previousFocus=null;}
function catPrompt(){showModal(`<img class="modal-cat-image" src="./assets/cat.jpeg" alt="Cat, chefe do setor"><div class="cat-modal-content"><div class="eyebrow">A CHEFE CHEGOU.</div><h2 id="modal-title">O QUE VOCÊ<br>IRÁ FAZER?</h2><p>Um cliente está esperando, Anderson.<br>Escolha sua resposta com cuidado.<br>Eu estou de olho.</p><button class="btn btn-primary" data-action="dismiss-prompt">Pode deixar, Cat. ${icon('arrow')}</button></div>`,'prompt');}
function newGame(){clearJobs();closeModal();stats.attempts++;write(STATS_KEY,stats);state={version:SAVE_VERSION,phase:'intro',introStep:0,introReady:false,introPrompted:false,messages:[],awaiting:'intro-0',baseDate:saoPauloDate(),mapSeed:Math.random()*1500,mapElapsed:0,tech:null,intakeIndex:0,asked:{},form:{name:'',vehicle:'',availability:''},intakeMessages:[],tab:'form',clipboard:null,calendarDay:null,calendarTime:null,completed:false};view='game';ensureJourney();state.customer=makeClient(state.caseId);createMainDesk();persist();audio.start();render({focus:true});window.scrollTo(0,0);schedulePending();}
function schedulePending(){if(!state?.awaiting)return;const expected=state.awaiting;delay(()=>{if(view!=='game'||state?.awaiting!==expected||state.failed)return;state.awaiting=null;if(expected.startsWith('intro-')){const step=Number(expected.slice(-1));state.messages.push({sender:'client',text:INTRO[step].incoming,time:state.messages.length});state.introReady=true;audio.effect('message');if(step===0&&!state.introPrompted){state.introPrompted=true;persist();render();catPrompt();return;}}else if(expected==='date'){state.messages.push({sender:'client',text:'Perfeito, quando tem data?',time:4});state.phase='map';audio.effect('message');}else if(expected.startsWith('field-')){const index=Number(expected.slice(-1)),f=FIELDS[index];state.asked[f.key]=true;const replies=state.customer?.replies?.[index]||[f.answer];for(let i=0;i<replies.length;i++)state.intakeMessages.push({sender:'client',text:replies[i],copyKey:i===replies.length-1?f.key:null,copyValue:answerFor(index),voice:state.customer?.variant===2,time:state.intakeMessages.length});audio.effect('message');}persist();render();},3000);}
function chooseIntro(index){if(lock||modal||!state.introReady||state.awaiting)return;desk?.checkpoint(state);desk?.record('intro:'+index,{progress:index===INTRO[state.introStep].correct});lock=true;const step=state.introStep;state.introReady=false;state.messages.push({sender:'player',text:INTRO[step].options[index],time:state.messages.length});render();if(index!==INTRO[step].correct){delay(()=>fail(INTRO[step].feedback[index]||'Essa resposta não seguiu a orientação do atendimento.'),450);return;}state.introStep++;if(state.introStep===1)state.awaiting='intro-1';else{state.introStep=1;state.awaiting='date';}lock=false;persist();render();schedulePending();}
function mapChoice(id){if(state.tech||lock||modal||!mapPoints)return;desk?.checkpoint(state);desk?.record('technician:'+id);lock=true;const rect=$('.map-world').getBoundingClientRect();const scale=p=>({...p,x:p.x*rect.width/1000,y:p.y*rect.height/570});const nearest=nearestIds(scale(mapPoints.client),mapPoints.techs.map(scale));cancelAnimationFrame(mapFrame);if(!nearest.includes(id)){fail(`No instante da sua escolha, o técnico mais próximo era o Anderson ${String(nearest[0]).padStart(2,'0')}.`);return;}state.tech=id;persist();audio.effect('success');lock=false;render();toast('Técnico certo! Agora vamos preencher o cadastro.');}
function beginIntake(){clearJobs();state.phase='intake';state.intakeMessages=[...state.messages];state.tab='form';persist();render({focus:true});window.scrollTo(0,0);}
function chooseIntake(index){if(lock||modal||state.awaiting)return;desk?.checkpoint(state);desk?.record('question:'+index,{progress:index===FIELDS[state.intakeIndex]?.correct});const f=FIELDS[state.intakeIndex];if(state.asked[f.key])return;lock=true;state.intakeMessages.push({sender:'player',text:f.options[index],time:state.intakeMessages.length});if(index!==f.correct){render();delay(()=>fail(f.feedback[index]||'A pergunta não corresponde ao dado solicitado nesta etapa.'),450);return;}state.awaiting=`field-${state.intakeIndex}`;lock=false;persist();render();schedulePending();}
async function copyAnswer(key){const msg=state.intakeMessages.find(m=>m.copyKey===key);if(!msg||msg.voice&&!state.voicesOpened?.[key])return;const value=msg.copyValue||msg.text;state.clipboard={key,value};desk?.record('copy:'+key);persist();audio.effect('copy');render();toast('Resposta copiada. Abra a ficha e use “Colar”.');try{await navigator.clipboard?.writeText(value);}catch{}}
async function pasteAnswer(){const f=FIELDS[state.intakeIndex];let value=state.clipboard?.value;if(!value){try{value=await navigator.clipboard?.readText();}catch{}}if(!value){toast('Primeiro, copie a resposta do cliente no WhatsApp.');return;}state.form[f.key]=value;persist();render();$(`#field-${f.key}`)?.focus({preventScroll:true});}
function saveField(){const f=FIELDS[state.intakeIndex],value=$(`#field-${f.key}`)?.value??state.form[f.key];state.form[f.key]=value;if(!state.asked[f.key]){const e=$('#form-error');e.textContent='Faça a pergunta ao cliente no WhatsApp antes de preencher.';return;}if(!validateField(state.intakeIndex,value,answerFor(state.intakeIndex))){const e=$('#form-error');e.textContent='Confira a resposta do cliente e cole a informação correta.';$(`#field-${f.key}`)?.focus();return;}audio.effect('copy');desk?.record('save-field:'+f.key,{progress:true});state.intakeIndex++;if(state.intakeIndex===FIELDS.length){state.phase='calendar';state.awaiting=null;}else state.tab='chat';persist();render({focus:state.phase==='calendar'});window.scrollTo({top:0,behavior:prefs.reduceMotion?'instant':'smooth'});}
function confirmBooking(){if(lock||!state.calendarDay||!state.calendarTime)return;desk?.checkpoint(state);desk?.record('confirm-booking');if(state.calendarDay!==addDays(state.baseDate,state.customer?.dayOffset||1)||state.calendarTime!==(state.customer?.time||'12:00')){showModal(`<span class="modal-client-angry" aria-hidden="true">A</span><div class="eyebrow">ANDERSON · CLIENTE</div><h3 id="modal-title">Você marcou errado!</h3><p class="angry-note">“Anderson, eu pedi: ${esc(answerFor(2))}”</p><button class="btn btn-secondary" data-action="booking-fail">${icon('arrow')} A Cat quer falar com você.</button>`,'angry');audio.effect('fail');return;}lock=true;state.intakeMessages.push({sender:'client',text:'Obrigado, Anderson! Confirmado para '+(state.customer?.time||'12:00')+'.'});state.phase='success';state.completed=true;desk?.finish();stats.wins++;write(STATS_KEY,stats);persist();lock=false;render();audio.effect('success');showModal(`<span class="avatar" style="margin-bottom:17px">A</span><div class="eyebrow">ANDERSON · CLIENTE</div><h3 id="modal-title">“Obrigado, Anderson!”</h3><p class="modal-text">Agendamento confirmado para ${state.customer?.time||'12:00'}.</p><button class="btn btn-primary" style="margin-top:23px" data-action="finish-success">Concluir atendimento ${icon('check')}</button>`,'thanks');}
function fail(reason){clearJobs();closeModal();state.failed=true;desk?.fail();audio.effect('fail');const canRetry=!!desk?.canRetry;if(canRetry)write(SAVE_KEY,{...desk.snapshot,journey:state.journey,failed:false,version:SAVE_VERSION});else remove(SAVE_KEY);showModal(`<div class="modal-cat-image failure-face">${portrait('cat','angry')}</div><div class="cat-modal-content"><div class="eyebrow">RECURSOS HUMANOS · AVISO IMEDIATO</div><h2 id="modal-title">ESTÁ<br>DEMITIDO!</h2><p>${esc(reason)}</p>${desk?.retryButton()||''}<button class="btn btn-secondary" data-action="return-menu">Voltar para o início ${icon('arrow')}</button><p class="checkpoint-note">${canRetry?'O checkpoint preservou esta etapa. A demissão entra na avaliação.':'Contrato de experiência: este expediente foi encerrado.'}</p></div>`,'failure');}
function ensureJourney(){if(!state||state.installationMode==='free')return;state.caseId??='anderson-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7);state.journey=restoreJourney(state.journey,state.caseId,prefs.difficulty);state.customer??={...makeClient('c'),name:state.form?.name||FIELDS[0].answer};for(const [act,done] of [[1,state.phase!=='intro'&&state.phase!=='map'&&state.phase!=='intake'&&state.phase!=='calendar'],[2,state.workshopCompleted],[3,state.activationCompleted],[4,state.heistCompleted],[5,state.recoveryCompleted]])if(done)state.journey=mergeMetrics(state.journey,act,{...state.journey.acts[act],completed:true});}
function createMainDesk(){desk=new ShiftSession({act:1,context:{caseId:state.caseId,mode:'campaign',difficulty:state.journey.difficulty,journey:state.journey,prefs},onMetrics:({act,metrics})=>{if(state?.caseId===desk?.context.caseId)state.journey=mergeMetrics(state.journey,act,metrics);}});if(desk.pendingRetry&&desk.canRetry){const snapshot=desk.retry(),journey=state.journey;state={...snapshot,journey,failed:false};}}
function answerFor(index){return [state.customer?.name,state.customer?.vehicle,state.customer?.availability][index]||FIELDS[index]?.answer;}
function retryMain(){if(!desk?.canRetry)return;const snapshot=desk.retry(),journey=state.journey;if(!snapshot)return;clearJobs();closeModal();state={...snapshot,journey,failed:false};view='game';persist();render({focus:true});schedulePending();window.scrollTo(0,0);}

function returnMenu(save=true){window.speechSynthesis?.cancel();clearJobs();if(save)persist();closeModal();view='menu';render();window.scrollTo(0,0);}
function showHelp(){showModal(`<button class="icon-button modal-close" data-action="close-modal" aria-label="Fechar ajuda">${icon('close')}</button><div class="eyebrow">MANUAL DE SOBREVIVÊNCIA</div><h3 id="modal-title">Como continuar empregado.</h3><div class="modal-text"><p><strong>Ato 5 · Atuação anti furto:</strong> atenda o cliente, classifique o caso, envie a localização à pronta resposta e dirija a viatura. A Rô acompanha a missão. Na perseguição, siga o Ford Ka e espere o aviso para bloquear.</p><p>Você é o Anderson do agendamento. Atenda o cliente, escolha o técnico mais próximo e preencha a ficha usando as respostas da conversa.</p><p><strong>Erros graves continuam dando demissão. Em Estagiário e Efetivado, você pode repetir do checkpoint. Contrato de experiência encerra a campanha.</strong> Na instalação 2D, erros fazem o carro explodir e encerram o expediente. No simulador 3D de prática, você pode corrigir a montagem. Quando isso acontecer, você volta ao início do ato. Sair pelo menu preserva o expediente em andamento.</p><p>No cadastro, use <strong>Copiar resposta</strong> na mensagem, abra a <strong>Ficha de agendamento</strong> e toque em <strong>Colar</strong>. Depois do agendamento, instale o LT-32 PRO no minigame 2D: escolha o local, ligue os fios, esconda e feche o veículo. O Ato 3 exige digitar o IMEI da foto, concluir 20 validações, solicitar a posição e enviar a localização ao técnico. Depois libere o acesso e envie o login e a senha ao cliente. Bear pressiona a ativação; a Cat demite quando você erra. No Ato 4, Anderson, o ladrão, anda pela cidade, encontra o Ford Ka, resolve o painel arcade e foge dirigindo. Use WASD, setas ou os controles na tela; E entra no carro. Errar o circuito chama a polícia e encerra a partida. O simulador 3D do LCV5 fica separado para prática. No PC, você também pode copiar e colar pelo teclado.</p></div><div class="help-controls"><div class="help-control"><strong>PC</strong>Mouse ou Tab + Enter.<br>Teclas 1–5 nas respostas.</div><div class="help-control"><strong>Celular</strong>Toque nas opções e técnicos.<br>Role a tela para ver tudo.</div></div><div class="settings-row"><div>Reduzir movimento<small>Pausa os marcadores do mapa e reduz animações.</small></div><button class="toggle ${prefs.reduceMotion?'':'off'}" data-action="motion">${prefs.reduceMotion?'Ativo':'Inativo'}</button></div><p class="muted" style="font-size:10px;margin:17px 0">Campanha individual. O progresso fica neste navegador; não é transferido entre aparelhos. Todo o atendimento é fictício.</p><button class="btn btn-primary btn-wide" data-action="close-modal">Entendi. Vamos trabalhar. ${icon('arrow')}</button>`,'help');}
function showMenuDialog(){showModal(`<button class="icon-button modal-close" data-action="close-modal" aria-label="Fechar menu">${icon('close')}</button><div class="eyebrow">PAUSA NO EXPEDIENTE</div><h3 id="modal-title">A Cat deixa. Por enquanto.</h3><p class="modal-text">Seu progresso está salvo. Você pode continuar este ato depois, no mesmo navegador.</p><div class="modal-menu-actions"><button class="btn btn-primary" data-action="close-modal">Continuar jogando ${icon('play')}</button><button class="btn btn-secondary" data-action="return-menu">Salvar e voltar ao início</button><button class="btn btn-ghost" data-action="restart-dialog">Recomeçar o ato</button></div>`,'menu');}
function restartDialog(){showModal(`<div class="eyebrow">NOVO EXPEDIENTE</div><h3 id="modal-title">Voltar à primeira mensagem?</h3><p class="modal-text">O progresso deste expediente será substituído por uma nova tentativa.</p><div class="button-row" style="margin-top:24px"><button class="btn btn-primary" data-action="new-game">Recomeçar</button><button class="btn btn-secondary" data-action="close-modal">Continuar este</button></div>`,'restart');}
function toggleSound(){prefs.sound=!prefs.sound;if(!prefs.sound)window.speechSynthesis?.cancel();write(PREFS_KEY,prefs);if(prefs.sound)audio.init();document.querySelectorAll('[data-action="sound"]').forEach(b=>{b.innerHTML=icon(prefs.sound?'volume':'muted');b.setAttribute('aria-label',`${prefs.sound?'Desativar':'Ativar'} som`);b.title=`${prefs.sound?'Desativar':'Ativar'} som`;});toast(prefs.sound?'Som ativado.':'Som desativado.');if(['workshop','activation','heist','recovery'].includes(state?.phase))sendWorkshopContext();}
function dispatch(action,button){
 if(action==='difficulty'){prefs.difficulty=difficultyFor(button.dataset.id).id;write(PREFS_KEY,prefs);render();return;}
 if(action==='records')return showModal(recordsMarkup(),'records');
 if(action==='retry-checkpoint')return retryMain();
 if(action==='open-voice'){const key=button.dataset.key;state.voicesOpened??={};state.voicesOpened[key]=true;desk?.record('voice:'+key,{progress:true});const msg=state.intakeMessages.find(m=>m.copyKey===key);try{if(prefs.sound&&msg&&window.speechSynthesis&&window.SpeechSynthesisUtterance){window.speechSynthesis.cancel();const voice=new SpeechSynthesisUtterance(msg.copyValue||msg.text);voice.lang='pt-BR';voice.rate=1.05;window.speechSynthesis.speak(voice);}}catch{}persist();render();return;}
 if(action==='new-game')return newGame();
 if(action==='continue'){const s=savedGame();if(s){clearJobs();state=s;state.failed=false;view='game';ensureJourney();createMainDesk();if(state.phase==='success')return beginWorkshop('campaign');if(state.phase==='workshop'&&state.workshopCompleted&&state.installationMode!=='free')return beginActivation();if(state.phase==='activation'&&state.activationCompleted)return beginHeist();if(state.phase==='heist'&&state.heistCompleted)return beginRecovery();audio.start();render();schedulePending();window.scrollTo(0,0);}return;}
 if(action==='free-workshop')return beginWorkshop('free');
 if(action==='lt32-solo')return beginWorkshop('lt32-free');
 if(action==='activation-solo')return beginActivation('activation-free');
 if(action==='heist-solo')return beginHeist('heist-free');
 if(action==='recovery-solo')return beginRecovery('recovery-free');
 if(action==='next-act')return beginWorkshop('campaign');
 if(action==='sound')return toggleSound();
 if(action==='help')return showHelp();
 if(action==='credits'){import('./credits.mjs?v=1.1.2').then(({creditsMarkup})=>{if(view==='menu')showModal(creditsMarkup(),'credits');}).catch(()=>toast('Não foi possível abrir os créditos. Tente novamente.'));return;}
 if(action==='menu-dialog')return showMenuDialog();
 if(action==='close-modal'||action==='dismiss-prompt'||action==='finish-success'){closeModal();return;}
 if(action==='motion'){prefs.reduceMotion=!prefs.reduceMotion;write(PREFS_KEY,prefs);document.body.classList.toggle('reduce-motion',prefs.reduceMotion);button.textContent=prefs.reduceMotion?'Ativo':'Inativo';button.classList.toggle('off',!prefs.reduceMotion);const label=$('.map-bar .mono');if(label)label.textContent=prefs.reduceMotion?'MOVIMENTO REDUZIDO':'POSIÇÕES EM MOVIMENTO';return;}
 if(action==='return-menu')return returnMenu();
 if(action==='restart-dialog')return restartDialog();
 if(action==='intro-choice')return chooseIntro(Number(button.dataset.index));
 if(action==='select-tech')return mapChoice(Number(button.dataset.id));
 if(action==='begin-intake')return beginIntake();
 if(action==='tab-form'||action==='tab-chat'){desk?.record('tab:'+action);state.tab=action==='tab-form'?'form':'chat';persist();render();return;}
 if(action==='intake-choice')return chooseIntake(Number(button.dataset.index));
 if(action==='copy')return copyAnswer(button.dataset.key);
 if(action==='paste')return pasteAnswer();
 if(action==='save-field')return saveField();
 if(action==='date'){state.calendarDay=button.dataset.date;persist();render();return;}
 if(action==='time'){state.calendarTime=button.dataset.time;persist();render();return;}
 if(action==='confirm-booking')return confirmBooking();
 if(action==='booking-fail')return fail('Agendamento errado. O cliente pediu: '+answerFor(2));
}
for(const root of [app,modalRoot])root.addEventListener('click',e=>{const b=e.target.closest('button[data-action]');if(b&&!b.disabled)dispatch(b.dataset.action,b);});
app.addEventListener('input',e=>{if(e.target.dataset.field&&state){state.form[e.target.dataset.field]=e.target.value;persist();}});
document.addEventListener('keydown',e=>{
 if(modal){if(e.key==='Escape'&&!['failure','prompt','angry','thanks'].includes(modal.kind)){e.preventDefault();closeModal();return;}if(e.key==='Tab'){const focusable=[...modalRoot.querySelectorAll('button:not(:disabled),input,a[href]')];const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){last?.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first?.focus();e.preventDefault();}}return;}
 if(e.target.matches('input,textarea,[contenteditable]'))return;
 if(view==='game'&&/^[1-5]$/.test(e.key)){const action=state.phase==='intro'?'intro-choice':state.phase==='intake'&&state.tab==='chat'?'intake-choice':null;if(action){const b=app.querySelector(`[data-action="${action}"][data-position="${Number(e.key)-1}"]`);if(b){e.preventDefault();b.click();}}}
 if(e.key==='Escape'&&view==='game')showMenuDialog();
});
window.addEventListener('pagehide',persist);
document.addEventListener('visibilitychange',()=>{if(document.hidden){persist();audio.ctx?.suspend().catch(()=>{});}else if(prefs.sound&&audio.ctx)audio.ctx.resume().catch(()=>{});});
render();

let lastDeskTick=performance.now();setInterval(()=>{const now=performance.now(),ms=now-lastDeskTick;lastDeskTick=now;if(view==='game'&&state&&!state.failed&&!modal&&!document.hidden&&['intro','map','intake','calendar'].includes(state.phase)){desk?.step(ms,state.phase,{waiting:!!state.awaiting});persist();}},1000);
